from common import *

write('k01-mindset', 'ذهنیت فروش مشاوره‌ای', f'''
<p class="lead">ما «کالا» نمی‌فروشیم؛ به یک انسان کمک می‌کنیم مهم‌ترین تصمیم چند سال آینده‌اش را درست بگیرد. فروشنده موفق خدمات آموزشی، <b>مشاور مورد اعتماد</b> است، نه فروشنده اصرارکننده.</p>
{goals(['تفاوت فروش معامله‌ای و مشاوره‌ای را بدانید.', 'اصول اعتمادسازی را به کار ببرید.', 'سفر تصمیم مشتری را بشناسید.'])}
<table><tr><th></th><th>فروش معامله‌ای</th><th>فروش مشاوره‌ای</th></tr>
<tr><td>تمرکز</td><td>محصول و قیمت</td><td>مشکل و هدف مشتری</td></tr>
<tr><td>گفتگو</td><td>فروشنده صحبت می‌کند</td><td>مشتری ۷۰٪ صحبت می‌کند</td></tr>
<tr><td>هدف تماس</td><td>بستن همین حالا</td><td>قدم بعدی مشخص</td></tr>
<tr><td>نتیجه بلندمدت</td><td>یک فروش</td><td>فروش + معرفی دوستان</td></tr></table>
<h3>معادله اعتماد</h3>
<p>مدل معروف <b>Trust Equation</b> (مایستر) می‌گوید اعتماد از چهار جزء ساخته می‌شود:</p>
<div class="formula"><math display="block"><mi>اعتماد</mi><mo>=</mo><mfrac><mrow><mi>اعتبار</mi><mo>+</mo><mi>اطمینان‌پذیری</mi><mo>+</mo><mi>صمیمیت</mi></mrow><mi>خودمحوری</mi></mfrac></math>
<p class="fdesc"><b>اعتبار:</b> دانش دقیق از محصول، بازار و قوانین. <b>اطمینان‌پذیری:</b> به قول‌ها عمل می‌کنید (وظایف SamenCRM!). <b>صمیمیت:</b> مشتری احساس امنیت می‌کند. <b>خودمحوری</b> (مخرج): هر چه بیشتر به فکر فروش خودتان باشید، اعتماد کمتر.</p></div>
<h3>سفر تصمیم مشتری</h3>
{flow([('آگاهی', 'مشکلی دارم که باید حل شود'), ('بررسی', 'راه‌حل‌ها، فروشندگان، هزینه'), ('مقایسه', 'ما در برابر دیگران'), ('تصمیم', 'مدارک و پرداخت'), ('تجربه', 'تحویل، راه‌اندازی، استفاده'), ('توصیه', 'معرفی دوستان', 'end')])}
<p>در هر مرحله، مشتری چیز متفاوتی لازم دارد: در «بررسی» اطلاعات، در «مقایسه» دلیل اعتماد، در «تصمیم» اطمینان و سادگی کار.</p>
{todo('mindset', ['در تماس بعدی، دست‌کم ۷۰٪ زمان را به شنیدن اختصاص دهید.', 'به همه قول‌هایتان وظیفه با تاریخ بدهید.', 'از هر مشتری خریدار بپرسید «چرا ما را انتخاب کردید؟» و یادداشت کنید.'])}
''')

write('k02-qualify', 'ارزیابی و امتیازدهی سرنخ (BANT، CHAMP، Lead Scoring)', f'''
<p class="lead">وقت محدود است. ارزیابی سرنخ یعنی سریع بفهمیم کدام مشتری آماده، توانا و علاقه‌مند است تا وقت بیشتری برای او بگذاریم.</p>
{goals(['چارچوب BANT و CHAMP را به کار ببرید.', 'به هر سرنخ امتیاز ۰ تا ۱۰۰ بدهید.', 'سرنخ‌ها را به داغ، گرم و سرد تقسیم کنید.'])}
<h3>BANT</h3>
<dl class="terms"><dt>Budget – بودجه</dt><dd>توان پرداخت هزینه‌ها (خرید، راه‌اندازی، نگهداری). «برای هزینه‌ها چه برنامه‌ای دارید؟»</dd>
<dt>Authority – اختیار</dt><dd>چه کسی تصمیم می‌گیرد؟ اغلب خانواده یا همسر. «چه کسی در این تصمیم با شماست؟»</dd>
<dt>Need – نیاز</dt><dd>مشکل و هدف مشتری. «این خرید قرار است چه مشکلی را برایتان حل کند؟»</dd>
<dt>Timeline – زمان</dt><dd>کی می‌خواهد شروع کند؟ «از چه تاریخی لازمش دارید؟»</dd></dl>
<p><b>CHAMP</b> همین چهار را با ترتیبی بهتر برای فروش مشاوره‌ای می‌پرسد: <b>Challenges</b> (چالش)، <b>Authority</b>، <b>Money</b>، <b>Prioritization</b> (اولویت). اول از مشکل بپرسید، نه از پول.</p>
<h3>امتیازدهی سرنخ</h3>
<table><tr><th>بخش</th><th>حداکثر</th><th>معیارها</th></tr>
<tr><td>تناسب (Fit)</td><td>۴۰</td><td>نیازش با محصول ما جور است (۱۵)، اندازه/توان مناسب (۱۰)، در منطقه خدمت ما است (۱۰)، اطلاعات تماس کامل (۵)</td></tr>
<tr><td>تعامل (Engagement)</td><td>۳۰</td><td>به پیام پاسخ داد (۱۰)، سؤال جزئی پرسید (۱۰)، مدرک فرستاد (۱۰)</td></tr>
<tr><td>آمادگی مالی</td><td>۲۰</td><td>بودجه را تأیید کرد (۲۰) / ابهام دارد (۱۰)</td></tr>
<tr><td>فوریت</td><td>۱۰</td><td>همین ماه (۱۰) / فصل بعد (۵)</td></tr></table>
<div class="formula"><math display="block"><mi>امتیاز</mi><mo>=</mo><mi>تناسب</mi><mo>+</mo><mi>تعامل</mi><mo>+</mo><mi>آمادگی مالی</mi><mo>+</mo><mi>فوریت</mi></math></div>
{calc('score')}
<table><tr><th>امتیاز</th><th>دسته</th><th>اقدام در SamenCRM</th></tr>
<tr><td>۷۰+</td><td>داغ</td><td>برچسب «داغ»، تماس امروز، فرصت با مبلغ</td></tr>
<tr><td>۴۰–۶۹</td><td>گرم</td><td>برنامه پیگیری ۱۴ روزه، محتوای آموزشی</td></tr>
<tr><td>زیر ۴۰</td><td>سرد</td><td>فهرست بلندمدت؛ پیام ماهانه</td></tr></table>
{todo('qualify', ['برای ۱۰ سرنخ اخیر امتیاز حساب کنید.', 'برچسب‌های «داغ»، «گرم»، «سرد» بسازید و بدهید.', 'داغ‌ها را امروز تماس بگیرید.'])}
{quiz([('مشتری بودجه دارد، نیازش با محصول ما جور است ولی برای سال بعد برنامه دارد. کجا قرار می‌گیرد؟', 'احتمالاً گرم: تناسب و پول بالا، فوریت پایین؛ پرورش با محتوا و پیگیری ماهانه.')])}
''')

write('k03-call', 'تماس اول: ساختار، اسکریپت و پیام', f'''
<p class="lead">تماس اول تعیین می‌کند مشتری شما را «یک مؤسسه دیگر» ببیند یا «مشاوری که به او اهمیت می‌دهد». ساختار ثابت داشته باشید تا هیچ بخشی جا نماند.</p>
{goals(['تماس اول را در ۶ مرحله اجرا کنید.', 'متن آماده برای تماس و پیام داشته باشید.', 'نتیجه را درست در SamenCRM ثبت کنید.'])}
{flow([('آماده‌سازی', '۳۰ ثانیه مرور پرونده'), ('شروع گرم', 'معرفی + اجازه'), ('کشف نیاز', 'پرسش‌های باز'), ('ارزش', 'پاسخ متناسب'), ('قدم بعدی', 'توافق مشخص'), ('ثبت', 'یادداشت + وظیفه', 'end')])}
<h3>متن پیشنهادی تماس</h3>
<div class="script">
<p><b>شروع:</b> «سلام آقای/خانم [نام]، [نام شما] هستم از شرکت ما. پیام شما درباره محصولاتمان را دیدم. الان ۵ دقیقه وقت دارید؟»</p>
<p><b>کشف نیاز:</b> «الان این کار را چطور انجام می‌دهید؟ … چه چیزی در روش فعلی آزارتان می‌دهد؟ … چه چیزی برایتان مهم‌تر است: قیمت، کیفیت یا سرعت تحویل؟»</p>
<p><b>جمع‌بندی:</b> «پس اگر درست فهمیده باشم، شما راه‌حلی می‌خواهید که تا پایان ماه راه بیفتد، کیفیت مهم است ولی هزینه نگهداری برایتان مهم‌تر است. درست است؟»</p>
<p><b>ارزش:</b> «سه بسته با این شرایط داریم؛ برایتان جدول مقایسه می‌فرستم.»</p>
<p><b>قدم بعدی:</b> «جدول را امروز در تلگرام می‌فرستم. پنجشنبه ساعت ۱۰ دوباره تماس بگیرم تا سؤال‌هایتان را جواب دهم؟»</p></div>
<h3>اگر جواب نداد: پیام</h3>
<div class="script"><p>«سلام [نام] عزیز 🌷 از شرکت ما هستم. درباره [محصول/خدمت] پیام داده بودید. برای اینکه بهترین پیشنهاد را آماده کنم، فقط بگویید: ۱) برای چه کاری لازم دارید ۲) چه تعداد/حجمی ۳) کی لازم دارید. ممنون!»</p></div>
<h3>ثبت در SamenCRM</h3>
{fig('profile-summary', 'بعد از تماس', ['نام.', 'ویرایش برای فیلدهای جدید.', 'ارسال جدول در تلگرام.', 'بیشتر.', 'برچسب «علاقه: …».', 'تب‌ها.', 'فیلدهای کلیدی.', 'افزودن رویداد «تماس پنجشنبه ۱۰».', 'یادداشت نتیجه.'])}
{todo('call', ['متن تماس را به زبان خودتان بازنویسی کنید.', 'با یک همکار نقش‌آفرینی کنید (۱۰ دقیقه).', 'سه تماس اول فردا را با این ساختار انجام دهید و یادداشت کنید.'])}
''')

write('k04-spin', 'کشف نیاز با پرسش‌های SPIN', f'''
<p class="lead">SPIN (نیل رکهام) روشی برای پرسیدن است که مشتری خودش به اهمیت تصمیم و ارزش کمک شما برسد. فروشنده‌ای که درست می‌پرسد، کمتر نیاز به متقاعد کردن دارد.</p>
{goals(['چهار نوع پرسش SPIN را بسازید.', 'از موقعیت به نیاز صریح برسید.'])}
<table><tr><th>نوع</th><th>هدف</th><th>نمونه برای مشتری</th></tr>
<tr><td><b>S</b>ituation – موقعیت</td><td>واقعیت‌ها</td><td>«الان کجا مشغول هستید؟ مدرک قبلی را کی گرفتید؟»</td></tr>
<tr><td><b>P</b>roblem – مشکل</td><td>نارضایتی‌ها</td><td>«با مدرک فعلی چه محدودیتی در کار دارید؟»</td></tr>
<tr><td><b>I</b>mplication – پیامد</td><td>بزرگ کردن هزینه مشکل</td><td>«اگر دو سال دیگر هم همین بماند، چه اثری روی درآمد و ارتقا دارد؟»</td></tr>
<tr><td><b>N</b>eed-payoff – ارزش راه‌حل</td><td>مشتری خودش ارزش را بگوید</td><td>«اگر این مشکل تا ماه بعد حل شود، چه چیزی برایتان تغییر می‌کند؟»</td></tr></table>
{flow([('S', 'موقعیت'), ('P', 'مشکل'), ('I', 'پیامد'), ('N', 'ارزش راه‌حل'), ('پیشنهاد', 'متناسب با پاسخ‌ها', 'end')])}
<div class="tip">پرسش‌های S را کم کنید؛ پاسخ بیشترشان در پرونده SamenCRM هست. وقت را برای P، I و N بگذارید.</div>
<div class="example"><b>گفتگو:</b> «سفارش‌ها را الان چطور ثبت می‌کنید؟» (S) – «چند سفارش در ماه گم یا دیر می‌شود؟» (P) – «هر سفارش دیرشده چقدر هزینه و نارضایتی دارد؟» (I) – «اگر هیچ سفارشی دیر نمی‌شد، چه چیزی تغییر می‌کرد؟» (N). حالا پیشنهاد شما، پاسخ به همان هدف است.</div>
{todo('spin', ['برای سه محصول پرفروش خود از هر نوع دو پرسش بنویسید.', 'پرسش‌ها را در یک قالب یادداشت ذخیره کنید.'])}
''')

write('k05-objections', 'پاسخ به اعتراض‌ها و نگرانی‌ها', f'''
<p class="lead">اعتراض یعنی مشتری هنوز در حال فکر کردن است، نه «نه». با روش درست، هر اعتراض فرصتی برای اعتمادسازی است.</p>
{goals(['روش LAER را اجرا کنید.', 'پاسخ اعتراض‌های رایج را آماده داشته باشید.'])}
<h3>روش LAER</h3>
{flow([('Listen', 'گوش دادن کامل'), ('Acknowledge', 'تأیید احساس'), ('Explore', 'پرسیدن علت واقعی'), ('Respond', 'پاسخ مشخص + مدرک', 'end')])}
<h3>اعتراض‌های رایج مشتریان خارجی</h3>
<table><tr><th>اعتراض</th><th>علت احتمالی</th><th>پاسخ پیشنهادی</th></tr>
<tr><td>«گران است»</td><td>مقایسه با گزینه ارزان‌تر یا نبود دید کامل هزینه</td><td>جدول هزینه کل در برابر ارزش (صرفه‌جویی، بازگشت سرمایه)؛ گزینه‌های پرداخت مرحله‌ای</td></tr>
<tr><td>«باید با خانواده مشورت کنم»</td><td>تصمیم‌گیرنده دیگری هست</td><td>«حتماً. چه اطلاعاتی برای خانواده لازم است؟ می‌توانم با هم تماس بگیریم؟» + وظیفه پیگیری</td></tr>
<tr><td>«از کجا بدانم نتیجه می‌دهد؟»</td><td>نگرانی از ریسک</td><td>نمونه کار، نظر مشتریان قبلی، دوره آزمایشی یا ضمانت</td></tr>
<tr><td>«کار با آن سخت است»</td><td>ترس از پیچیدگی</td><td>آموزش، راه‌اندازی توسط ما، پشتیبانی</td></tr>
<tr><td>«مؤسسه دیگری ارزان‌تر است»</td><td>مقایسه قیمت</td><td>تفاوت خدمات (پشتیبانی، ضمانت، سرعت)؛ هرگز بدگویی از رقیب</td></tr>
<tr><td>«بعداً»</td><td>نبود فوریت</td><td>مهلت‌های واقعی فروش و ظرفیت؛ تاریخ مشخص برای تماس بعد</td></tr></table>
<div class="warn">هرگز اطلاعات نادرست یا قولی که نمی‌توانید عمل کنید ندهید. اعتماد ازدست‌رفته برنمی‌گردد و مشتری به ده نفر دیگر می‌گوید.</div>
<p>هر اعتراض را با برچسب <code>اعتراض: قیمت</code>، <code>اعتراض: خانواده</code>… ثبت کنید. ماهانه گزارش بگیرید؛ پرتکرارترین اعتراض، مهم‌ترین موضوع محتوای بازاریابی ماه بعد است.</p>
{todo('obj', ['برای هر اعتراض جدول، پاسخ را به زبان خودتان بنویسید.', 'برچسب‌های اعتراض را بسازید.', 'جدول هزینه کل را از مدیر بگیرید و در اسناد بارگذاری کنید.'])}
''')

write('k06-closing', 'بستن فروش، پرداخت و تحویل پرونده', f'''
<p class="lead">بستن یعنی کمک به مشتری برای گرفتن تصمیمی که خودش به آن رسیده است. اگر نیازسنجی درست انجام شده باشد، بستن طبیعی است.</p>
{goals(['نشانه‌های آمادگی را تشخیص دهید.', 'از روش‌های بستن مناسب استفاده کنید.', 'پرونده را برای مرحله مدارک تحویل دهید.'])}
<h3>نشانه‌های خرید</h3>
<ul><li>سؤال درباره جزئیات اجرایی: «مدارک را چطور بفرستم؟»، «کی باید پرداخت کنم؟»</li><li>صحبت با زمان آینده: «وقتی راه افتاد…»</li><li>درگیر کردن خانواده برای پرداخت.</li></ul>
<h3>روش‌های بستن</h3>
<table><tr><th>روش</th><th>نمونه</th></tr>
<tr><td>جمع‌بندی</td><td>«بسته حرفه‌ای، راه‌اندازی تا ۱۵ آذر، هزینه کل Y. شروع کنیم؟»</td></tr>
<tr><td>انتخاب بین دو گزینه</td><td>«بسته A را ترجیح می‌دهید یا B؟»</td></tr>
<tr><td>قدم کوچک</td><td>«فعلاً فقط پاسپورت و ریزنمرات را بفرستید تا ارزیابی را شروع کنیم.»</td></tr>
<tr><td>مهلت واقعی</td><td>«تخفیف این جشنواره تا ۲۰ آذر است؛ قرارداد باید تا ۱۸ آذر امضا شود.»</td></tr></table>
<h3>پس از «بله»</h3>
{flow([('فاکتور', 'ارسال فاکتور = بله'), ('پرداخت', 'شماره رسید'), ('قرارداد', 'امضا و بارگذاری در اسناد'), ('تحویل', 'شروع کار / ارسال'), ('آموزش', 'راه‌اندازی برای مشتری'), ('موفق', 'مرحله فروش = موفق', 'end')])}
{fig('profile-details', 'فیلدهای روند کار و پرداخت را به‌روز کنید', ['اطلاعات پایه.', 'موبایل.', 'مسئول.', 'مشخصات مشتری.', 'گروه مشتری.', 'شعبه.', 'محصول موردعلاقه.'])}
{todo('close', ['برای هر مشتری «بله»، فیلدهای فاکتور، رسید و وضعیت مدارک را پر کنید.', 'فهرست مدارک لازم را در تلگرام بفرستید.', 'وظیفه پیگیری مدارک با سررسید ۳ روزه بسازید.'])}
''')

write('k07-retention', 'پس از فروش: رضایت، ارجاع و NPS', f'''
<p class="lead">ارزان‌ترین مشتری جدید، دوست یک مشتری راضی است. فروش با فروش تمام نمی‌شود؛ تازه شروع رابطه است.</p>
{goals(['برنامه خوش‌آمد و پیگیری پس از فروش بسازید.', 'شاخص NPS را بسنجید.', 'برنامه معرفی (ارجاع) اجرا کنید.'])}
{flow([('روز خرید', 'خوش‌آمد + راهنمای شروع'), ('هفته ۲', 'تماس رضایت'), ('ماه ۱', 'نظرسنجی NPS'), ('هر فصل', 'بررسی رضایت و نیاز جدید'), ('تولد', 'تبریک خودکار'), ('ارجاع', 'معرفی دوستان', 'end')])}
<h3>NPS – شاخص خالص ترویج‌کنندگان</h3>
<p>یک سؤال: «از ۰ تا ۱۰ چقدر احتمال دارد ما را به یک دوست معرفی کنید؟» ۹–۱۰ ترویج‌کننده، ۷–۸ خنثی، ۰–۶ منتقد.</p>
<div class="formula"><math display="block"><mi>NPS</mi><mo>=</mo><mi>٪ترویج‌کنندگان</mi><mo>−</mo><mi>٪منتقدان</mi></math><p class="fdesc">بازه از ۱۰۰- تا ۱۰۰+. بالای ۳۰ خوب، بالای ۵۰ عالی.</p></div>
{calc('nps')}
<h3>برنامه معرفی</h3>
<ol><li>فهرست ترویج‌کنندگان (۹–۱۰) را با برچسب <code>ترویج‌کننده</code> بسازید.</li><li>پیام شخصی: «از اینکه راضی هستید خوشحالیم؛ اگر دوستی دارید که می‌خواهد در ایران درس بخواند، لینک زیر را برایش بفرستید.»</li><li>مشتری معرفی‌شده را با منبع سرنخ = «معرفی دوستان» و فیلد «گزارش به» = معرف ثبت کنید.</li><li>از معرف تشکر کنید (هدیه/تخفیف طبق سیاست مؤسسه).</li></ol>
{todo('retention', ['برای مشتریان جدید این ماه تماس رضایت هفته دوم را زمان‌بندی کنید.', 'نظرسنجی NPS را با تلگرام بفرستید.', 'NPS را حساب کنید و منتقدان را امروز تماس بگیرید.'])}
''')

write('k08-metrics', 'ریاضیات فروش: نرخ تبدیل، سرعت خط لوله و پیش‌بینی', f'''
<p class="lead">مدیر فروش خوب با عدد حرف می‌زند. با چند فرمول ساده می‌توانید درآمد ماه بعد را پیش‌بینی کنید و بفهمید کدام اهرم بیشترین اثر را دارد.</p>
{goals(['نرخ تبدیل و نرخ موفقیت را محاسبه کنید.', 'سرعت خط لوله را بفهمید و اهرم‌هایش را بشناسید.', 'پیش‌بینی وزنی بسازید.'])}
<h3>۱. نرخ موفقیت (Win Rate)</h3>
<div class="formula"><math display="block"><mi>Win Rate</mi><mo>=</mo><mfrac><mi>فرصت‌های موفق</mi><mrow><mi>موفق</mi><mo>+</mo><mi>ناموفق</mi></mrow></mfrac></math><p class="fdesc">فقط فرصت‌های بسته‌شده را حساب کنید؛ فرصت باز در مخرج نیست.</p></div>
<h3>۲. سرعت خط لوله (Pipeline Velocity)</h3>
<div class="formula"><math display="block"><mi>V</mi><mo>=</mo><mfrac><mrow><mi>N</mi><mo>×</mo><mi>A</mi><mo>×</mo><mi>W</mi></mrow><mi>L</mi></mfrac></math><p class="fdesc">N: تعداد فرصت‌های باز، A: میانگین ارزش هر فرصت، W: نرخ موفقیت، L: طول چرخه فروش (روز). خروجی: درآمد در روز.</p></div>
{calc('velocity')}
<div class="example">۶۰ فرصت، میانگین ۴۰ میلیون ریال، نرخ موفقیت ۲۵٪، چرخه ۳۰ روز ⇒ V = ۶۰×۴۰,۰۰۰,۰۰۰×۰٫۲۵ ÷ ۳۰ = ۲۰ میلیون ریال در روز. اگر چرخه را با پیگیری سریع‌تر به ۲۰ روز برسانید، V به ۳۰ میلیون می‌رسد (۵۰٪ رشد بدون حتی یک سرنخ بیشتر).</div>
<h3>۳. پیش‌بینی وزنی</h3>
<div class="formula"><math display="block"><mi>پیش‌بینی</mi><mo>=</mo><munder><mo>∑</mo><mi>i</mi></munder><msub><mi>مبلغ</mi><mi>i</mi></msub><mo>×</mo><msub><mi>احتمال</mi><mi>i</mi></msub></math></div>
<table><tr><th>مرحله</th><th>احتمال پیشنهادی</th><th>مجموع مبلغ</th><th>وزنی</th></tr>
<tr><td>ارزیابی</td><td>۱۰٪</td><td>۵۰۰ م</td><td>۵۰ م</td></tr><tr><td>پیشنهاد</td><td>۳۰٪</td><td>۳۰۰ م</td><td>۹۰ م</td></tr>
<tr><td>مدارک</td><td>۶۰٪</td><td>۲۰۰ م</td><td>۱۲۰ م</td></tr><tr><td>پرداخت اولیه</td><td>۹۰٪</td><td>۱۰۰ م</td><td>۹۰ م</td></tr>
<tr><th colspan="3">پیش‌بینی ماه</th><th>۳۵۰ م</th></tr></table>
{calc('forecast')}
<h3>۴. اهرم‌های رشد</h3>
<p>درآمد = سرنخ × نرخ تبدیل × میانگین ارزش. افزایش ۱۰٪ هر کدام، درآمد را ۱۰٪ بالا می‌برد؛ افزایش ۱۰٪ هر سه با هم ⇒ ۱٫۱³ = ۱٫۳۳۱ یعنی <b>۳۳٪ رشد</b>.</p>
{todo('metrics', ['Win Rate سه ماه گذشته خود را حساب کنید.', 'سرعت خط لوله تیم را با ماشین‌حساب بالا محاسبه کنید.', 'برای فرصت‌های باز احتمال واقعی بگذارید و پیش‌بینی وزنی ماه را بسازید.'])}
{quiz([('۲۰ فرصت موفق، ۶۰ ناموفق و ۴۰ باز داریم. Win Rate؟', '۲۰ ÷ (۲۰+۶۰) = ۲۵٪. فرصت‌های باز حساب نمی‌شوند.'), ('بزرگ‌ترین اهرم سرعت خط لوله بدون هزینه بازاریابی؟', 'کوتاه کردن چرخه فروش (L) با پیگیری سریع و منظم، یا بالا بردن نرخ موفقیت (W).')])}
''')
print('course 4 written')
